async function handleLogin(request, env) {
  const hashes = accessCodeHashes(env);
  if (!env.PITCH_SESSION_SECRET || !hashes) {
    return json({ ok: false, message: "This pitch Worker has not been configured yet." }, 503);
  }
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ ok: false, message: "Enter your access code." }, 400);
  }
  if (!body || typeof body.code !== "string" || body.code.length > 128) {
    return json({ ok: false, message: "Enter your access code." }, 400);
  }
  const suppliedHash = await sha256Hex(body.code.trim());
  let account = null;
  for (const candidate of ACCOUNTS) {
    const expectedHash = hashes[candidate.id];
    const candidateHash = typeof expectedHash === "string" ? expectedHash : "0".repeat(64);
    if (constantTimeEqual(suppliedHash, candidateHash) && typeof expectedHash === "string") account = candidate;
  }
  if (!account) {
    return json({ ok: false, message: "That access code is not valid." }, 401);
  }
  const session = await createSession(account, env);
  return json({ ok: true }, 200, {
    "Set-Cookie": SESSION_COOKIE + "=" + session + "; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=" + SESSION_MAX_AGE_SECONDS,
  });
}

// Shared by the Experimental presentation and prospect API. All prices are USD.
const PITCH_SERVICE_CATALOG = Object.freeze({
  website: { name: 'Website', price: 2000, stage: 'evaluate' },
  seo: { name: 'Lifetime Regular SEO', price: 0, stage: 'discover' },
  reviews: { name: 'Google Review System', price: 1000, stage: 'evaluate' },
  crm: { name: 'Custom-built CRM', price: 1000, stage: 'respond' },
  chatbot: { name: 'AI Chatbot', price: 1000, monthlyPercent: 3, stage: 'enquire' },
  receptionist: { name: 'AI Receptionist', price: 1000, monthlyPercent: 3, stage: 'respond' },
  googleAds: { name: 'Google Advertising', price: 1000, monthlyPercent: 3, stage: 'discover' },
  metaAds: { name: 'Meta Advertising', price: 1000, monthlyPercent: 3, stage: 'discover' },
  ecommerce: { name: 'Full E-Commerce', price: 1000, stage: 'evaluate' },
  apps: { name: 'iOS + Android App', price: 3000, stage: 'evaluate' },
});

function fixedPitchPricing(source = {}) {
  const supplied = Array.isArray(source.services) ? source.services : [];
  // Older Paid Ads selections need an explicit platform choice, not a guess.
  const legacyAds = supplied.includes('ads');
  const services = Object.keys(PITCH_SERVICE_CATALOG).filter(id => id === 'website' || supplied.includes(id));
  if (legacyAds) services.push('ads');
  const priced = services.filter(id => id !== 'ads');
  const setup = priced.reduce((total, id) => total + PITCH_SERVICE_CATALOG[id].price, 0);
  const recurring = priced.filter(id => PITCH_SERVICE_CATALOG[id].monthlyPercent);
  const monthlyPercent = recurring.reduce((total, id) => total + PITCH_SERVICE_CATALOG[id].monthlyPercent, 0);
  // Every fixed price is a whole dollar. Multiplication yields exact cents.
  const monthlyCents = setup * monthlyPercent;
  return { services, setup, monthly: monthlyCents / 100, monthlyPercent, recurring, legacyAds };
}

// A private, durable prospect library per authenticated account.
export class PitchProspects extends DurableObject {
  async list(cursor = '') {
    const records = await this.ctx.storage.list({ prefix: 'person:', limit: 51, ...(cursor ? { startAfter: cursor } : {}) });
    const entries = [...records.entries()];
    const page = entries.slice(0, 50);
    return {
      people: page.map(([, record]) => ({ id: record.id, customerName: record.values.customerName, businessName: record.values.businessName, updatedAt: record.updatedAt })),
      cursor: entries.length > 50 ? page.at(-1)[0] : null,
    };
  }
  async get(id) {
    return (await this.ctx.storage.get('person:' + id)) || null;
  }
  async save(id, values, revision) {
    const key = 'person:' + id;
    return this.ctx.storage.transaction(async transaction => {
      const previous = await transaction.get(key);
      if ((previous?.revision || 0) !== revision) return { conflict: true };
      const record = { id, values, revision: revision + 1, updatedAt: new Date().toISOString() };
      await transaction.put(key, record);
      return { record };
    });
  }
}

const PROSPECT_MAX_MONEY_CENTS = 99999999999999n;
const PROSPECT_MAX_JOB_COUNT = 1000000000n;

function prospectMoney(input, allowEmpty = false) {
  if (input !== undefined && typeof input !== 'string' && typeof input !== 'number') return null;
  if (typeof input === 'number' && !Number.isFinite(input)) return null;
  const text = input === undefined ? '' : String(input).trim();
  if (!text) return { value: allowEmpty ? '' : '0', cents: allowEmpty ? null : 0n };
  if (text.length > 32 || !/^\d+(?:\.\d{1,2})?$/.test(text)) return null;
  const [whole, fraction = ''] = text.split('.');
  const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, '0'));
  if (cents > PROSPECT_MAX_MONEY_CENTS) return null;
  const remainder = String(cents % 100n).padStart(2, '0').replace(/0+$/, '');
  return { value: String(cents / 100n) + (remainder ? '.' + remainder : ''), cents };
}

function prospectJobCount(input) {
  if (input !== undefined && typeof input !== 'string' && typeof input !== 'number') return null;
  if (typeof input === 'number' && !Number.isFinite(input)) return null;
  const text = input === undefined ? '' : String(input).trim();
  if (!text) return { value: '', count: null };
  if (text.length > 32 || !/^\d+$/.test(text)) return null;
  const count = BigInt(text);
  return count <= PROSPECT_MAX_JOB_COUNT ? { value: String(count), count } : null;
}

function prospectValues(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const result = {};
  for (const [key, max] of [['customerName',100],['businessName',180]]) {
    if (typeof input[key] !== 'string' || input[key].length > max) return null;
    result[key] = input[key].trim();
  }
  if (!result.customerName || !result.businessName) return null;
  for (const [key, max] of [['marketingWhat',1200],['marketingImpact',1200],['marketingTimeline',1200]]) {
    const value = input[key] === undefined ? '' : input[key];
    if (typeof value !== 'string' || value.length > max) return null;
    result[key] = value.trim();
  }
  for (const key of ['manualAverageJobValue']) {
    const money = prospectMoney(input[key]);
    if (!money) return null;
    result[key] = money.value;
  }
  for (const key of ['averageJobValue']) {
    const mode = input[key + 'Mode'] === undefined ? 'amount' : input[key + 'Mode'];
    if (!['amount','slider'].includes(mode)) return null;
    result[key + 'Mode'] = mode;
  }
  for (const prefix of ['monthlyOpportunity','currentMonthlyRevenue']) {
    const amount = prospectMoney(input[prefix]);
    const mode = input[prefix + 'Mode'] === undefined ? 'amount' : input[prefix + 'Mode'];
    const jobs = prospectJobCount(input[prefix + 'Jobs']);
    const jobValue = prospectMoney(input[prefix + 'JobValue'], true);
    if (!amount || !['amount','jobs','slider'].includes(mode) || !jobs || !jobValue) return null;
    // Incomplete job inputs are a saved draft, retaining the last manual amount.
    // Completed formulas are compared in cents, without floating-point rounding.
    if (mode === 'jobs' && jobs.count !== null && jobValue.cents !== null) {
      const product = jobs.count * jobValue.cents;
      if (product > PROSPECT_MAX_MONEY_CENTS || product !== amount.cents) return null;
    }
    result[prefix] = amount.value;
    result[prefix + 'Mode'] = mode;
    result[prefix + 'Jobs'] = jobs.value;
    result[prefix + 'JobValue'] = jobValue.value;
  }
  // Pricing uses an active top-level calculator, then the explicit manual
  // fallback. A selected zero wins; the legacy average field is never trusted.
  result.averageJobValue = result.monthlyOpportunityMode === 'jobs' && result.monthlyOpportunityJobValue !== ''
    ? result.monthlyOpportunityJobValue
    : result.currentMonthlyRevenueMode === 'jobs' && result.currentMonthlyRevenueJobValue !== ''
      ? result.currentMonthlyRevenueJobValue
      : result.manualAverageJobValue;
  const allowedGaps = ['visibility','conversion','calls','followup','reviews','admin','phone','leadflow','adresults'];
  const allowedServices = [...Object.keys(PITCH_SERVICE_CATALOG), 'ads'];
  for (const [key,allowed] of [['gaps',allowedGaps],['services',allowedServices]]) {
    if (!Array.isArray(input[key]) || input[key].some(value => !allowed.includes(value))) return null;
    result[key] = [...new Set(input[key])];
  }
  const pricing = fixedPitchPricing(result);
  result.services = pricing.services;
  result.standardPrice = String(pricing.setup);
  result.monthlyFee = String(pricing.monthly);
  result.standardPriceMode = result.monthlyFeeMode = 'amount';
  return result;
}

async function handleProspects(request, env, account) {
  if (!account) return json({message:'Sign in required.'},401);
  if (account.id !== 'experimental') return json({message:'Not found.'},404);
  if (!env.PITCH_PROSPECTS) return json({message:'Saved people are temporarily unavailable. Your current pitch is safe.'},503);
  const url = new URL(request.url);
  const id = url.pathname.slice('/api/prospects'.length).replace(/^\//,'');
  if (id && !/^[0-9a-f-]{36}$/i.test(id)) return json({message:'Invalid person.'},400);
  const library = env.PITCH_PROSPECTS.getByName(account.id);
  try {
    if (request.method === 'GET' && !id) {
      const cursor = url.searchParams.get('cursor') || '';
      if (cursor && !/^person:[0-9a-f-]{36}$/i.test(cursor)) return json({message:'Invalid page.'},400);
      return json(await library.list(cursor));
    }
    if (request.method === 'GET' && id) {
      const person = await library.get(id);
      if (!person) return json({message:'Person not found.'},404);
      // Project valid older records into the current contract without writing
      // them back or changing their revision, ID or timestamps.
      const values = prospectValues(person.values);
      return json({person: values ? {...person,values} : person});
    }
    if (request.method !== 'PUT' || !id) return json({message:'Method not allowed.'},405);
    if (request.headers.get('Origin') !== url.origin) return json({message:'Request not allowed.'},403);
    if (!request.headers.get('Content-Type')?.startsWith('application/json')) return json({message:'JSON required.'},415);
    // Bound both declared and streamed body size before parsing.
    if (Number(request.headers.get('Content-Length')) > 10000) return json({message:'Person details are too large.'},413);
    const reader = request.body?.getReader();
    if (!reader) return json({message:'Person details required.'},400);
    const chunks = []; let size = 0;
    while (true) {
      const {done,value} = await reader.read();
      if (done) break;
      size += value.length;
      if (size > 10000) { await reader.cancel(); return json({message:'Person details are too large.'},413); }
      chunks.push(value);
    }
    const bytes = new Uint8Array(size); let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk,offset); offset += chunk.length; }
    let body;
    try { body = JSON.parse(new TextDecoder().decode(bytes)); } catch { return json({message:'Invalid person details.'},400); }
    const values = prospectValues(body?.values);
    if (!values || !Number.isSafeInteger(body.revision) || body.revision < 0) return json({message:'Add a customer and business name, and check the values.'},400);
    const saved = await library.save(id,values,body.revision);
    if (saved.conflict) return json({message:'This person was updated elsewhere. Your edits are still here; reopen the saved person before changing it.'},409);
    return json({person:saved.record});
  } catch {
    console.error(JSON.stringify({event:'prospect_storage_unavailable',accountId:account.id}));
    return json({message:'Could not reach saved people. Your current pitch has not been cleared. Try again.'},503);
  }
}


/** @type {ExportedHandler<Env>} */
export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === "POST" && url.pathname === "/api/login") {
      return handleLogin(request, env);
    }

    if (request.method === "POST" && url.pathname === "/api/logout") {
      return json({ ok: true }, 200, {
        "Set-Cookie": SESSION_COOKIE + "=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0",
      });
    }

    const account = await verifySession(request, env);

    if (url.pathname === "/api/prospects" || url.pathname.startsWith("/api/prospects/")) {
      return handleProspects(request, env, account);
    }

    if (request.method === "GET" && url.pathname === "/") {
      if (!account) return response(loginPage(configured(env)));
      return response(stagePage(account), {
        headers: { "X-Pitch-Revision": DECK_REVISIONS.experimental, "Permissions-Policy":"fullscreen=(self)" },
      });
    }

    if (request.method === "GET" && url.pathname === "/api/deck") {
      if (!account) return response("Sign in required.", { status: 401, contentType: "text/plain; charset=utf-8" });
      const storagePrefix = "pitch:v31:experimental:";
      const deck = DECKS.experimental.replaceAll("__PITCH_STORAGE_PREFIX__", storagePrefix);
      return response(deck, {
        headers: {
          "Content-Security-Policy": "frame-ancestors 'self'",
          "X-Pitch-Revision": DECK_REVISIONS.experimental,
          "Permissions-Policy":"fullscreen=(self)",
        },
      });
    }

    if (request.method === "HEAD" && url.pathname === "/") {
      return response("");
    }

    return response("Not found.", { status: 404, contentType: "text/plain; charset=utf-8" });
  },
};
